 try{$r=packaging_source((int)($_GET['id']??0));}catch(Throwable $e){echo '<div class="alert danger">'.e($e->getMessage()).'</div>';return;}$id=(int)$r['id'];$s=stock_row($r['product_id']);
 ?>
