 <?php packaging_action_fields('packaging_complete','packaging_detail&id='.$id);?><input type="hidden" name="source_id" value="<?=$id?>"><input type="hidden" name="signature" value="<?=e(packaging_signature($id))?>"><input type="hidden" name="completion_ref" value="<?=e('PACK-'.date('Ymd-His').'-'.bin2hex(random_bytes(6)))?>">
 <div class="grid two"><label>Approval Date<input type="date" name="txn_date" value="<?=date('Y-m-d')?>" required></label><label>Quantity Ready for Sale<input type="number" name="qty" min="1" max="<?=$r['remaining']?>" step="1" required></label></div>
 <h4>Allocate All Ready Units</h4><div class="grid three"><?php foreach(['Shopee','Lazada','TikTok'] as $platform):?><label><?=e($platform)?><input type="number" name="allocation[<?=$platform?>]" min="0" step="1" value="0" required></label><?php endforeach;?></div>
