 echo '<div class="card table-wrap"><h3>Ready for Sale History</h3><table class="table"><tr><th>Record / Date</th><th>Quantity</th><th>Platform Allocation</th><th>Approved By</th><th>Remarks / Status</th></tr>';foreach($q as $c){$a=json_decode($c['allocation_json'],true);echo '<tr><td>PC-'.$c['id'].'<br>'.e($c['txn_date']).'</td><td>'.(int)$c['qty'].' pcs</td><td>'.e(implode(' · ',array_map(fn($pl)=>$pl.' '.$a[$pl],['Shopee','Lazada','TikTok']))).'</td><td>'.e($c['approved_name']).'</td><td>'.e($c['reason']).'<br>'.($c['reversed_by_request']?'Reversed':'Confirmed').'</td></tr>';}echo '</table><p class="muted small">For an incorrect approval, request a linked Packaging Completion reversal from Transaction Corrections using its PC record ID.</p></div>';return;
}
