$qText=trim($_GET['q']??'');$history=($_GET['history']??'')==='all';$params=[];$sql='SELECT n.*,p.name,p.master_sku,u.name owner_name,COALESCE((SELECT SUM(l.qty) FROM nonsellable_release_links l WHERE l.non_sellable_id=n.id),0) linked_out FROM non_sellable n JOIN products p ON p.id=n.product_id LEFT JOIN users u ON u.id=n.packaging_owner_id WHERE n.qty>0';
if($qText!==''){$sql.=' AND (p.name LIKE ? OR p.master_sku LIKE ? OR n.order_id LIKE ?)';$params=array_fill(0,3,'%'.$qText.'%');}$sql.=' ORDER BY n.id DESC';$st=db()->prepare($sql);$st->execute($params);$filtered=[];
foreach($st as $row){$remaining=max(0,(int)$row['qty']-(int)$row['linked_out']);if(packaging_kind($row['condition_type'])!==$view)continue;if(!$history&&(!$remaining||$row['reversed_by_request']!==null))continue;$row['remaining']=$remaining;$filtered[]=$row;}
$offset=$history?max(0,(int)($_GET['offset']??0)):0;$rows=array_slice($filtered,$offset,$history?50:10);
?>
