<?php foreach($rows as $r):$state=$r['reversed_by_request']?'Reversed':($r['remaining']?($r['packaging_state']??$r['status']):'Completed / Released');?><tr><td><b><?=e($r['name'])?></b><br><?=e($r['master_sku'])?></td><td><?=e($r['txn_date'])?><br><?=e($r['order_id'])?></td><td><?=e($r['condition_type'])?></td><td><?=(int)$r['qty']?> / <b><?=$r['remaining']?> pcs</b></td><td><?=e($r['owner_name']??'Unassigned')?><br><?=e($r['packaging_due_date']??'No target date')?><?php if($r['remaining']&&$r['packaging_due_date']&&$r['packaging_due_date']<date('Y-m-d')):?><br><b class="num-red">Overdue</b><?php endif;?></td><td><?=e($state)?><br><a class="btn ghost sm" href="?page=<?=$view==='packaging'&&$r['reversed_by_request']===null?'packaging_detail':'nonsellable_detail'?>&id=<?=(int)$r['id']?>"><?=$view==='packaging'?'Manage / Ready for Sale':'View Details'?></a></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="6">No records for this view.</td></tr><?php endif;?></table>
<?php if($history)echo rs8_pagination(count($filtered),$offset,50,array_replace($_GET,['page'=>'nonsellable','stock_view'=>$view,'history'=>'all']));?></div>
